// What a planet's house placement is read as, before the house's own wherePhrase.
export const houseMeanings = {
  sun: 'where you most want to shine and feel alive',
  moon: 'where you seek comfort and belonging',
  mercury: 'where your mind is busiest',
  venus: 'where you find pleasure, beauty and harmony',
  mars: 'where you push hardest and meet conflict',
  jupiter: 'where opportunities and growth come most easily',
  saturn: 'where you are tested and build mastery over time',
  uranus: 'where you need freedom and where life changes suddenly',
  neptune: 'where you idealise, dream and may lose your footing',
  pluto: 'where you meet intensity and are remade',
  ascendant: 'how you start things and meet the world',
  midheaven: 'what you aim to be known for',
  northNode: 'where growth asks you to stretch',
};

export function ordinal(n) {
  const s = n % 100;
  if (s >= 11 && s <= 13) return `${n}th`;
  return n + ({ 1: 'st', 2: 'nd', 3: 'rd' }[n % 10] ?? 'th');
}

function article(word) {
  return /^[aeiou]/i.test(word) ? 'an' : 'a';
}

function cap(s) {
  return s.charAt(0).toUpperCase() + s.slice(1);
}

/**
 * Build the plain-English grammar sentence for a placement.
 * Returns { heading, sentence, parts: [{ role: 'what'|'how'|'where', label, source, text }],
 *           houseNote, reading: { title, text } | null }
 * so the UI can show each part of the sentence coming from its source.
 */
export function composePlacement(planetId, signId, houseNumber) {
  const p = planets[planetId];
  const s = signs[signId];
  if (!p) throw new Error(`composePlacement: unknown planet "${planetId}"`);
  if (!s) throw new Error(`composePlacement: unknown sign "${signId}"`);
  const h = houseNumber == null ? null : houses[houseNumber];
  if (houseNumber != null && !h) throw new Error(`composePlacement: unknown house "${houseNumber}"`);

  const how = `in ${article(s.howPhrase)} ${s.howPhrase} way`;
  const parts = [
    { role: 'what', label: 'What', source: p.name, text: p.whatPhrase },
    { role: 'how', label: 'How', source: s.name, text: how },
  ];
  if (h) parts.push({ role: 'where', label: 'Where', source: `${ordinal(h.number)} house`, text: h.wherePhrase });

  const heading = `${p.name} in ${s.name}${h ? ` in the ${ordinal(h.number)} house` : ''}`;
  const sentence = `Astrologers read ${heading} as ${p.whatPhrase}, expressed ${how}${h ? `, showing up mainly ${h.wherePhrase}` : ''}.`;
  const houseNote = h && houseMeanings[planetId]
    ? `${cap(houseMeanings[planetId])}: ${h.wherePhrase}.`
    : null;
  const reading = placements[planetId]?.[signId] ?? (planetId === 'ascendant' ? rising[signId] : null) ?? null;
  return { heading, sentence, parts, houseNote, reading };
}

/**
 * Build the sentence for an aspect between two chart points.
 * Returns { heading, sentence, parts }.
 */
export function composeAspect(aId, bId, aspectId) {
  const a = planets[aId];
  const b = planets[bId];
  const asp = aspects[aspectId];
  if (!a || !b) throw new Error(`composeAspect: unknown body "${!a ? aId : bId}"`);
  if (!asp) throw new Error(`composeAspect: unknown aspect "${aspectId}"`);
  const heading = `${a.name} ${asp.verb} ${b.name}`;
  const sentence = `Astrologers read ${heading} as a conversation between ${a.whatPhrase} (${a.name}) and ${b.whatPhrase} (${b.name}): the two ${asp.talkPhrase}.`;
  const parts = [
    { role: 'what', label: 'What', source: a.name, text: a.whatPhrase },
    { role: 'talk', label: 'How they talk', source: asp.name, text: asp.talkPhrase },
    { role: 'what', label: 'What', source: b.name, text: b.whatPhrase },
  ];
  return { heading, sentence, parts };
}
